static int
sip_compute(
    /*@unused@*/ const unsigned int naxes,
    const unsigned int nelem,
    const unsigned int m,
    /*@null@*/ const double* a,
    const unsigned int n,
    /*@null@*/ const double* b,
    const double* crpix /* [2] */,
    /*@null@*/ double* tmp,
    /*@null@*/ const double* input /* [NAXES][nelem] */,
    /*@null@*/ double* output /* [NAXES][nelem] */) {

input_ptr = input;
output_ptr = output;
for (i = 0; i < nelem; ++i) {
  x = *input_ptr++ - crpix[0];
  y = *input_ptr++ - crpix[1];

  for (j = 0; j <= (int)m; ++j) {
    tmp[j] = lu(m, a, (int)m-j, j);
    for (k = j-1; k >= 0; --k) {
      tmp[j] = (y * tmp[j]) + lu(m, a, (int)m-j, k);
    }
  }

  sum = tmp[0];
  for (j = (int)m; j > 0; --j) {
    sum = x * sum + tmp[(int)m - j + 1];

int
sip_pix2deltas(
    const sip_t* sip,
    const unsigned int naxes,
    const unsigned int nelem,
    const double* pix /* [NAXES][nelem] */,
    double* deltas /* [NAXES][nelem] */) {

  if (sip == NULL) {
    return 1;
  }

  return sip_compute(naxes, nelem,
                     sip->a_order, sip->a,
                     sip->b_order, sip->b,
                     sip->crpix,
                     (double *)sip->scratch,
                     pix, deltas);
